        self.assertEqual(late_fee(100_000, DUE, late(36)), 3023 + 500)
        self.assertEqual(late_fee(100_000, DUE, late(66)), 4568 + 500)
        self.assertEqual(late_fee(100_000, DUE, late(96)), 6137 + 500)

